import GRDB
import Foundation

/// Records every row an import writes (before and after, as JSON) using temporary triggers that
/// live only on the importing connection, so the run can be undone. Use `begin` before the
/// writes and `finish` (or `cancel`) in the same transaction/connection afterwards.
public enum ImportChangeCapture {
    /// Tables whose writes are not logged: the import log itself, the forecast tables
    /// (regenerated by `AutoForecastGenerator.refresh`, which only inserts) and bookkeeping, among it
    /// the sync tables: undoing an import must never revert sync identities, tombstones or state.
    static let untrackedTables: Set<String> = [
        "importRun", "importChange", "importRunFile", "forecastEntry", "forecastGroup", "grdb_migrations",
        "syncRecord", "syncStaging", "syncConflict", "syncTombstone", "syncState",
        "syncPending", "syncFieldClock", "syncWriter", "syncApplying", "syncBatch", "syncBatchMember",
        "syncZoneMove", "syncCompanion", "syncAccessRevert", "syncPresence", "syncZoneCleanup",
    ]

    private static let triggerPrefix = "importCapture_"

    private static func quoted(_ name: String) -> String {
        "\"" + name.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    static func trackedTables(db: Database) throws -> [String] {
        try String.fetchAll(db, sql: "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
            .filter { !untrackedTables.contains($0) }
    }

    static func blobColumns(db: Database, table: String) throws -> Set<String> {
        Set(try db.columns(in: table).filter { $0.type.uppercased() == "BLOB" }.map(\.name))
    }

    /// Columns with REAL affinity (declared type containing REAL, FLOA or DOUB, not INT).
    static func realColumns(db: Database, table: String) throws -> Set<String> {
        Set(try db.columns(in: table).filter { column in
            let type = column.type.uppercased()
            return !type.contains("INT") && (type.contains("REAL") || type.contains("FLOA") || type.contains("DOUB"))
        }.map(\.name))
    }

    /// `json_object('col', <prefix>."col", ...)` with BLOB columns as `hex(...)` (a NULL BLOB
    /// stays `null`, not `""`, so undo restores it as NULL) and REAL values as text with 17
    /// significant digits (`printf('%!.17g')`), so they round-trip exactly.
    private static func jsonExpression(db: Database, table: String, prefix: String?) throws -> String {
        let blobs = try blobColumns(db: db, table: table)
        let reals = try realColumns(db: db, table: table)
        let pairs = try db.columns(in: table).map { column -> String in
            let ref = (prefix.map { $0 + "." } ?? "") + quoted(column.name)
            let value: String
            if blobs.contains(column.name) {
                value = "CASE WHEN \(ref) IS NULL THEN NULL ELSE hex(\(ref)) END"
            } else if reals.contains(column.name) {
                value = "CASE WHEN typeof(\(ref)) = 'real' THEN printf('%!.17g', \(ref)) ELSE \(ref) END"
            } else {
                value = ref
            }
            return "'" + column.name.replacingOccurrences(of: "'", with: "''") + "', \(value)"
        }
        return "json_object(" + pairs.joined(separator: ", ") + ")"
    }

    public static func begin(db: Database) throws {
        try cancel(db: db)
        try db.execute(sql: """
            CREATE TEMP TABLE importCapture(
                seq INTEGER PRIMARY KEY AUTOINCREMENT,
                tableName TEXT NOT NULL, rowId INTEGER NOT NULL, op TEXT NOT NULL,
                beforeJSON TEXT, afterJSON TEXT)
            """)
        for table in try trackedTables(db: db) {
            let newJSON = try jsonExpression(db: db, table: table, prefix: "NEW")
            let oldJSON = try jsonExpression(db: db, table: table, prefix: "OLD")
            let name = table.replacingOccurrences(of: "'", with: "''")
            let t = quoted(table)
            func trigger(_ suffix: String, _ event: String, _ row: String, _ op: String, _ before: String, _ after: String) -> String {
                """
                CREATE TEMP TRIGGER \(quoted(triggerPrefix + table + "_" + suffix)) AFTER \(event) ON main.\(t)
                BEGIN
                    INSERT INTO temp.importCapture(tableName, rowId, op, beforeJSON, afterJSON)
                    VALUES ('\(name)', \(row).rowid, '\(op)', \(before), \(after));
                END
                """
            }
            try db.execute(sql: trigger("ins", "INSERT", "NEW", "insert", "NULL", newJSON))
            try db.execute(sql: trigger("upd", "UPDATE", "NEW", "update", oldJSON, newJSON))
            try db.execute(sql: trigger("del", "DELETE", "OLD", "delete", oldJSON, "NULL"))
        }
    }

    public static func finish(db: Database, runId: Int64) throws -> [ImportChange] {
        let rows = try Row.fetchAll(db, sql: "SELECT seq, tableName, rowId, op, beforeJSON, afterJSON FROM temp.importCapture ORDER BY seq")
        var written: [ImportChange] = []
        let identities = try db.tableExists("syncRecord") && db.tableExists("syncTombstone") && db.columns(in: "importChange").contains { $0.name == "rowUuid" }
        for row in rows {
            let table: String = row["tableName"], rowId: Int64 = row["rowId"]
            let operation = ImportChangeOperation(rawValue: row["op"])!
            // The row's sync identity now: a deleted row's is its tombstone, the run's own deletion.
            var rowUuid: String?
            if identities, SyncSchema.table(table) != nil {
                rowUuid = operation == .delete
                    ? try String.fetchOne(db, sql: """
                        SELECT uuid FROM syncTombstone WHERE tableName = ? AND localId = ? AND mergedInto IS NULL ORDER BY deletedAt DESC LIMIT 1
                        """, arguments: [table, rowId])
                    : try SyncRecordStore.existingUUID(table: table, localId: rowId, db: db)
            }
            var change = ImportChange(
                runId: runId, seq: row["seq"], tableName: table, rowId: rowId,
                operation: operation,
                beforeJSON: row["beforeJSON"], afterJSON: row["afterJSON"], rowUuid: rowUuid)
            try change.insert(db)
            written.append(change)
        }
        try cancel(db: db)
        return written
    }

    public static func cancel(db: Database) throws {
        let triggers = try String.fetchAll(db, sql: "SELECT name FROM sqlite_temp_master WHERE type = 'trigger' AND name LIKE 'importCapture\\_%' ESCAPE '\\'")
        for name in triggers { try db.execute(sql: "DROP TRIGGER IF EXISTS temp.\(quoted(name))") }
        try db.execute(sql: "DROP TABLE IF EXISTS temp.importCapture")
    }

    /// The row's current state in the same JSON shape the triggers record.
    public static func rowJSON(db: Database, table: String, rowId: Int64) throws -> String? {
        let expr = try jsonExpression(db: db, table: table, prefix: nil)
        return try String.fetchOne(db, sql: "SELECT \(expr) FROM \(quoted(table)) WHERE rowid = ?", arguments: [rowId])
    }
}
